function scopedDataBootstrap(): string {
  let source = DATA_CENTER_SCRIPT.slice(DATA_CENTER_SCRIPT.indexOf('{') + 1, DATA_CENTER_SCRIPT.lastIndexOf('})();'));
  source = source.slice(0, source.lastIndexOf('}'));
  source = source.replace("  const $ = id => document.getElementById(id);", "  const $ = id => ctx.root.querySelector('[data-dc-id=\"' + id + '\"]');");
  source = source.replace("  const base = location.pathname.replace(/\\/ops-observability\\/data-center\\/?$/, '');", '  const base = ctx.base;');
  source = source.replace('  consumeCredentials();', '');
  const headersStart = source.indexOf('  function authHeaders(mutation) {');
  const headersEnd = source.indexOf('  function identity() {', headersStart);
  source = source.slice(0, headersStart) + '  function authHeaders(mutation) { return ctx.headers(mutation); }\n' + source.slice(headersEnd);
  source = source.replace(/  function identity\(\) \{[^\n]+\}/, '  function identity() { return String(ctx.identity()); }');
  source = source.replaceAll('document.querySelectorAll', 'ctx.root.querySelectorAll').replaceAll("'[data-view]'", "'[data-dc-view]'").replaceAll('node.dataset.view', 'node.dataset.dcView').replace("node.id === 'manifest'", "node.dataset.dcId === 'manifest'");
  source = source.replace(/  function navigate\(view\) \{[^\n]+\}/, "  function navigate(view) { if (state.busy || !['overview','assets','tasks','datasets','loops'].includes(view)) return; state.view = view; ctx.navigate('data/' + view); render(); }");
  source = source.slice(0, source.indexOf("  $('consoleLink').href"));
  return 'function createDataCenterWorkspace(ctx) {' + source + `\n  let pendingRefresh = false; const scopedSetBusy = setBusy; setBusy = function(value) { scopedSetBusy(value); if(!value && pendingRefresh) Promise.resolve().then(()=>{ if(state.busy)return; pendingRefresh=false; return refresh(); }); };\n  return { show(child='assets') { if (state.loadedIdentity && state.loadedIdentity !== identity()) clearPrivate('账号或租户已变化，请刷新后重新读取数据。'); state.view=['overview','assets','tasks','datasets','loops'].includes(child)?child:'assets'; render(); if(!state.ready) { if(state.busy) { pendingRefresh=true; return; } return refresh(); } }, refresh, hide() { pendingRefresh=false; $('editor').close(); $('editorFields').replaceChildren(); submitHandler=null; }, reset() { state.generation++; clearPrivate('请刷新后重新读取数据。'); }, isBusy() { return state.busy; } };\n}`;
}

export const DATA_CENTER_WORKSPACE_BOOTSTRAP = scopedDataBootstrap();
